INSERT INTO SEARCH.POLICY_CHUNK (chunk_id, document, section, parent_section, page, page_to, chunk_text) VALUES
  ('POL-001', 'documents/bsa_aml_policy.pdf', 'Title page', '', 1, 1, 'Kestrel Valley Bank Bank Secrecy Act / Anti-Money Laundering Program Policy Version 7.2 - effective 1 July 2026 - approved by the Board of Directors on 24 June 2026 Synthetic document. Kestrel Valley Bank and Pellbrook Savings Bank are fictional. This policy was generated for a software demonstration. Regulatory references are summarised for illustration only and are not legal advice.'),
  ('POL-002', 'documents/bsa_aml_policy.pdf', '1. Purpose and scope', '', 2, 2, 'Purpose and scope. This policy sets out how Kestrel Valley Bank (the Bank) meets its obligations under the Bank Secrecy Act and related anti-money-laundering requirements. It applies to every account, product and channel of the Bank. Merger scope. On 30 June 2026 the Bank completed its acquisition of Pellbrook Savings Bank. Until core conversion is complete, customer accounts are held on two core systems: Core A (legacy Kestrel Valley) and Core B (legacy Pellbrook). Both cores belong to one legal entity. Every requirement in this policy applies across both cores as if they were a single system.'),
  ('POL-003', 'documents/bsa_aml_policy.pdf', '2. Governance', '', 2, 2, 'Governance. The Board approves this policy at least annually. The BSA Officer is responsible for day-to-day compliance, reports to the Board Risk Committee quarterly and has authority to escalate any matter directly to the Board. Model and rule changes in transaction monitoring require BSA Officer approval and are logged with the date, the change and the rationale.'),
  ('POL-004', 'documents/bsa_aml_policy.pdf', '3.1 Customer identification', '3. Customer due diligence', 2, 2, 'Customer identification. Identity is verified at account opening under the Customer Identification Program.'),
  ('POL-005', 'documents/bsa_aml_policy.pdf', '3.2 Customer risk profile', '3. Customer due diligence', 2, 2, 'Customer risk profile. Each customer has a documented profile of expected activity, including expected monthly cash and wire activity, occupation or line of business, and source of funds.'),
  ('POL-006', 'documents/bsa_aml_policy.pdf', '3.3 Enhanced due diligence', '3. Customer due diligence', 2, 2, 'Enhanced due diligence. EDD applies to customers rated High risk, cash-intensive businesses, customers with a SAR filed in the last 24 months, and customers whose observed activity materially exceeds the expected activity in their profile.'),
  ('POL-007', 'documents/bsa_aml_policy.pdf', '3.4 Profiles held on two cores', '3. Customer due diligence', 2, 2, 'Profiles held on two cores. Where the same customer holds relationships on both cores, the investigator must compare both profiles. A material inconsistency between them (for example, a different occupation or source of funds) is itself a red flag and must be resolved before an alert is closed.'),
  ('POL-008', 'documents/bsa_aml_policy.pdf', '4.1 Threshold', '4. Currency transaction reporting', 3, 3, 'Threshold. A Currency Transaction Report (CTR) is filed for each deposit, withdrawal, exchange or other payment or transfer involving more than $10,000 in currency.'),
  ('POL-009', 'documents/bsa_aml_policy.pdf', '4.2 Aggregation', '4. Currency transaction reporting', 3, 3, 'Aggregation. Multiple currency transactions by or on behalf of the same person on the same business day are treated as a single transaction when the Bank has knowledge of them and they total more than $10,000. Cash in and cash out are aggregated separately. Following the Pellbrook acquisition, currency transactions conducted on Core A and on Core B are known to the Bank and must be aggregated together. Until conversion, BSA Operations runs a daily cross-core cash aggregation report and files any CTR it identifies.'),
  ('POL-010', 'documents/bsa_aml_policy.pdf', '4.3 Filing deadline', '4. Currency transaction reporting', 3, 3, 'Filing deadline. CTRs are filed electronically within 15 calendar days after the transaction.'),
  ('POL-011', 'documents/bsa_aml_policy.pdf', '4.4 Exemptions', '4. Currency transaction reporting', 3, 3, 'Exemptions. Exemptions are granted only through the documented exemption process and reviewed annually.'),
  ('POL-012', 'documents/bsa_aml_policy.pdf', '5.1 Definition', '5. Structuring', 3, 3, 'Definition. Structuring is breaking up currency transactions to evade a reporting or recordkeeping requirement. It is prohibited regardless of whether the underlying funds are legitimate.'),
  ('POL-013', 'documents/bsa_aml_policy.pdf', '5.2 Red flags', '5. Structuring', 3, 3, 'Red flags. Repeated cash deposits just below $10,000; deposits spread across branches, accounts or days; a customer asking about reporting thresholds; cash activity inconsistent with the customer profile; and cash split between Core A and Core B accounts of the same customer.'),
  ('POL-014', 'documents/bsa_aml_policy.pdf', '5.3 Cross-core review', '5. Structuring', 3, 3, 'Cross-core review. When a structuring alert is investigated, the investigator must review the customer''s activity on both cores for the same period, using the unified customer view.'),
  ('POL-015', 'documents/bsa_aml_policy.pdf', '5.4 Action', '5. Structuring', 3, 3, 'Action. Suspected structuring is escalated for SAR consideration. Staff must never advise a customer how to avoid a report.'),
  ('POL-016', 'documents/bsa_aml_policy.pdf', '6.1 Triage', '6. Monitoring and alert handling', 4, 4, 'Triage. New alerts are triaged within 5 business days.'),
  ('POL-017', 'documents/bsa_aml_policy.pdf', '6.2 Investigation', '6. Monitoring and alert handling', 4, 4, 'Investigation. Investigations are completed within 30 calendar days of the alert date. Alerts open longer than 30 days are reported weekly to the BSA Officer as overdue.'),
  ('POL-018', 'documents/bsa_aml_policy.pdf', '6.3 Documentation', '6. Monitoring and alert handling', 4, 4, 'Documentation. Every closure records the facts reviewed, the rationale, the documents relied on and the investigator. A closure without a rationale is not permitted.'),
  ('POL-019', 'documents/bsa_aml_policy.pdf', '6.4 Quality assurance', '6. Monitoring and alert handling', 4, 4, 'Quality assurance. Ten percent of closed alerts are re-reviewed each month by a second investigator.'),
  ('POL-020', 'documents/bsa_aml_policy.pdf', '6.5 Prioritisation', '6. Monitoring and alert handling', 4, 4, 'Prioritisation. Alerts are worked in order of risk score. Scores must show the reasons that produced them.'),
  ('POL-021', 'documents/bsa_aml_policy.pdf', '7.1 When to file', '7. Suspicious Activity Reports', 4, 4, 'When to file. A SAR is considered for transactions that may involve money laundering, BSA violations (including structuring) or other suspicious activity, subject to the regulatory dollar thresholds.'),
  ('POL-022', 'documents/bsa_aml_policy.pdf', '7.2 Deadline', '7. Suspicious Activity Reports', 4, 4, 'Deadline. A SAR is filed no later than 30 calendar days after initial detection of facts that may constitute a basis for filing. If no suspect is identified, filing may be delayed an additional 30 days to identify one, but never beyond 60 days after initial detection.'),
  ('POL-023', 'documents/bsa_aml_policy.pdf', '7.3 Continuing activity', '7. Suspicious Activity Reports', 4, 4, 'Continuing activity. Continuing activity is reviewed at least every 90 days after a SAR is filed.'),
  ('POL-024', 'documents/bsa_aml_policy.pdf', '7.4 Confidentiality', '7. Suspicious Activity Reports', 4, 4, 'Confidentiality. The existence of a SAR must never be disclosed to the subject.'),
  ('POL-025', 'documents/bsa_aml_policy.pdf', '8.1 Definition', '8. Dormant and inactive accounts', 5, 5, 'Definition. An account with no customer-initiated activity for 12 months is classified as dormant.'),
  ('POL-026', 'documents/bsa_aml_policy.pdf', '8.2 Reactivation', '8. Dormant and inactive accounts', 5, 5, 'Reactivation. Reactivation requires identity re-verification by the branch or contact centre.'),
  ('POL-027', 'documents/bsa_aml_policy.pdf', '8.3 Monitoring', '8. Dormant and inactive accounts', 5, 5, 'Monitoring. An inflow of $10,000 or more within 30 days of reactivation, followed by rapid withdrawal, is reviewed as potential account takeover or use of the account as a pass-through.'),
  ('POL-028', 'documents/bsa_aml_policy.pdf', '9. Rapid movement of funds', '', 5, 5, 'Rapid movement of funds. When 90 percent or more of an inbound transfer of $25,000 or more leaves the account within 48 hours, with no documented business purpose, the activity is reviewed as possible pass-through or funnel activity. Investigators confirm the relationship between the customer, the originator and the beneficiaries.'),
  ('POL-029', 'documents/bsa_aml_policy.pdf', '10.1 Records', '10. Recordkeeping, training and testing', 6, 6, 'Records. BSA records, including CTRs, SARs and supporting documentation, are kept for at least five years.'),
  ('POL-030', 'documents/bsa_aml_policy.pdf', '10.2 Training', '10. Recordkeeping, training and testing', 6, 6, 'Training. All customer-facing and operations staff complete BSA training annually; investigators complete advanced training.'),
  ('POL-031', 'documents/bsa_aml_policy.pdf', '10.3 Independent testing', '10. Recordkeeping, training and testing', 6, 6, 'Independent testing. The BSA/AML program is independently tested at least every 12 to 18 months.'),
  ('POL-032', 'documents/bsa_aml_policy.pdf', 'Appendix A. Reporting obligations at a glance', '', 6, 6, 'Reporting obligations at a glance. CTR: cash over $10,000 per person per business day, aggregated across both cores; file within 15 days. SAR: within 30 days of initial detection (60 days if no suspect identified); review continuing activity every 90 days. Alert SLA: triage in 5 business days; resolve in 30 calendar days. Dormancy: 12 months without customer-initiated activity.');
